import{_ as n,o as r,c as i,a3 as t}from"./chunks/framework.z_KJ15Ep.js";const o=JSON.parse('{"title":"Serienbriefe und Bescheinigungen","description":"","frontmatter":{},"headers":[],"relativePath":"reporting/serienbriefe.md","filePath":"reporting/serienbriefe.md"}'),a={name:"reporting/serienbriefe.md"};function s(d,e,l,u,h,g){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="serienbriefe-und-bescheinigungen" tabindex="-1">Serienbriefe und Bescheinigungen <a class="header-anchor" href="#serienbriefe-und-bescheinigungen" aria-label="Permalink to &quot;Serienbriefe und Bescheinigungen&quot;">​</a></h1><p>Verbinden Sie einen wiederverwendbaren Briefkopf mit eigenen Texten und den Daten der ausgewählten Schülerinnen und Schüler. Für besondere Anlässe stehen vorbereitete Reports und Bescheinigungen bereit.</p><h2 id="einen-serienbrief-vorbereiten-und-ausgeben" tabindex="-1">Einen Serienbrief vorbereiten und ausgeben <a class="header-anchor" href="#einen-serienbrief-vorbereiten-und-ausgeben" aria-label="Permalink to &quot;Einen Serienbrief vorbereiten und ausgeben&quot;">​</a></h2><ol><li>Richten Sie den Briefkopf ein: <a href="/reporting/serienbriefe/basisreportsammlung-serienbriefe.html">Serienbriefe einrichten und drucken</a>.</li><li>Erstellen Sie den Text oder laden Sie eine vorhandene RTF-Datei: <a href="/reporting/serienbriefe/basisreportsammlung-einen-serienbrieftext-erstellen-schritt-fuer-schritt.html">Serienbrieftexte erstellen und wiederverwenden</a>.</li><li>Setzen Sie die passenden <a href="/reporting/serienbriefe/platzhalter.html">Platzhalter</a> für Namen, Anreden und weitere Angaben ein.</li><li>Wählen Sie die Schülergruppe und kontrollieren Sie die erzeugten Briefe in der Vorschau.</li></ol><h2 id="den-besonderen-anlass-wahlen" tabindex="-1">Den besonderen Anlass wählen <a class="header-anchor" href="#den-besonderen-anlass-wahlen" aria-label="Permalink to &quot;Den besonderen Anlass wählen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aufgabe</th><th>Anleitung</th></tr></thead><tbody><tr><td>Mahnungen vorbereiten und ausgeben</td><td><a href="/reporting/reportdesigner/mahnbriefe-drucken-tutorial.html">Mahnbriefe drucken</a></td></tr><tr><td>Aufgabe und Vorgaben des Mahnbriefs nachschlagen</td><td><a href="/reporting/serienbriefe/basisreportsammlung-serienbrief-mahnung-gefaehrdete-versetzung.html">Serienbrief zur Mahnung bei gefährdeter Versetzung</a></td></tr><tr><td>Anschreiben zur Nichtversetzung erstellen</td><td><a href="/reporting/serienbriefe/basisreportsammlung-serienbrief-nichtversetzung.html">Serienbriefe zur Nichtversetzung erstellen</a></td></tr><tr><td>Bilingualen Bildungsgang bescheinigen</td><td><a href="/reporting/serienbriefe/basisreportsammlung-bescheinigungen-des-bilingualen-bildungsgangs.html">Bescheinigungen für den bilingualen Bildungsgang erstellen</a></td></tr><tr><td>Stammblatt oder Schulbescheinigung direkt öffnen</td><td><a href="/reporting/serienbriefe/direkter-zugriff-auf-das-schuelerstammblatt-und-die-schulbescheinigung.html">Stammblatt und Schulbescheinigung direkt aufrufen</a></td></tr></tbody></table><h2 id="reportausgaben-per-e-mail-versenden" tabindex="-1">Reportausgaben per E-Mail versenden <a class="header-anchor" href="#reportausgaben-per-e-mail-versenden" aria-label="Permalink to &quot;Reportausgaben per E-Mail versenden&quot;">​</a></h2><p>Für individuell zugeordnete PDF-Anhänge lesen Sie <a href="/reporting/reportdesigner/serien-e-mail-versand.html">Reportausgaben als Serien-E-Mail versenden</a>. Die Nachrichtentexte können Sie über <a href="/reporting/reportdesigner/interne-texte-verwaltung-einstellungen.html">E-Mail-Standardtexte festlegen</a> vorbelegen. Einen einzelnen Report versenden Sie mit <a href="/reporting/reportverwaltung/einen-report-per-e-mail-versenden-und-teilen.html">Einen Report per E-Mail versenden und teilen</a>.</p>',8)])])}const f=n(a,[["render",s]]);export{o as __pageData,f as default};
